//! Opening book: positions (by `State::frontier_hash`) to weighted candidate actions.
//! Compiled in from `data/book_theory.txt`, generated by `ktools bookgen` from the source.
//! `play` actions are played; `know` actions are theory kept only for the positions they reach.

use crate::core::action::Action;
use crate::core::perft::parse_g_line;
use crate::core::state::State;
use std::collections::HashMap;
use std::sync::OnceLock;

/// Weight of an action that transposes into a position with played book actions.
pub const TRANSPOSE_WEIGHT: u32 = 3;

/// One candidate action of a book position.
#[derive(Clone, Debug)]
pub struct BookMove {
    pub action: Action,
    /// The action's LAN tokens (as in a 5DUCI move list).
    pub lan: String,
    /// The action in 5dpgn (short notation), for display.
    pub pgn: String,
    /// The engine may play it (otherwise it is only known theory).
    pub play: bool,
    /// Relative weight among the position's `play` actions.
    pub weight: u32,
}

/// A book position with the moves of each history reaching it, since past boards affect travels.
/// Unknown histories get the moves the known ones agree on; on `{exact}` lines, as known only.
#[derive(Default, Debug)]
struct Entry {
    /// Moves by history (`State::hash`).
    exact: Vec<(u64, Vec<BookMove>)>,
    /// For a history the book does not know: the actions the known histories agree on (played if all
    /// play it, at the lowest weight), the others as known theory; all known if `exact_only`.
    merged: Vec<BookMove>,
    /// Only valid for its own history (`E` line).
    exact_only: bool,
}

#[derive(Default, Debug)]
pub struct Book {
    positions: HashMap<u64, Entry>,
    /// Opening names (`N` lines): "Family: Variation: Line", by the position they are reached at.
    names: HashMap<u64, String>,
    /// Every distinct action of the book (LAN, 5dpgn), for `transpositions`.
    all_actions: OnceLock<Vec<(String, String)>>,
}

impl Book {
    /// Parse a book file. Every action is checked legal in its position.
    pub fn parse(text: &str) -> Result<Book, String> {
        let mut book = Book::default();
        let mut cur: Option<(u64, u64, State)> = None;
        for (n, line) in text.lines().enumerate() {
            let line = line.trim();
            let err = |e: String| format!("book line {}: {}", n + 1, e);
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            if let Some(g) = line.strip_prefix("P ") {
                let s = parse_g_line(g).map_err(err)?;
                let h = s.frontier_hash();
                let hist = s.hash();
                let e = book.positions.entry(h).or_default();
                if !e.exact.iter().any(|(x, _)| *x == hist) {
                    e.exact.push((hist, Vec::new()));
                }
                cur = Some((h, hist, s));
            } else if line == "E" {
                let (h, _, _) = cur.as_ref().ok_or_else(|| err("E before any position".into()))?;
                book.positions.get_mut(h).unwrap().exact_only = true;
            } else if let Some(name) = line.strip_prefix("N ") {
                let (h, _, _) = cur.as_ref().ok_or_else(|| err("name before any position".into()))?;
                // (Move orders reaching one position may be named differently: the first stays.)
                book.names.entry(*h).or_insert_with(|| name.trim().to_string());
            } else if let Some(m) = line.strip_prefix("m ") {
                let (h, hist, s) = cur.as_ref().ok_or_else(|| err("move before any position".into()))?;
                let (head, pgn) = m.split_once(';').unwrap_or((m, ""));
                let mut it = head.split_whitespace();
                let play = match it.next() {
                    Some("play") => true,
                    Some("know") => false,
                    k => return Err(err(format!("bad tag {:?}", k))),
                };
                let weight: u32 = it.next().and_then(|w| w.parse().ok()).ok_or_else(|| err("bad weight".into()))?;
                let lan = it.collect::<Vec<_>>().join(" ");
                let moves = crate::web::tree::parse_lan_moves(&lan).map_err(err)?;
                if moves.is_empty() {
                    return Err(err("empty action".into()));
                }
                crate::web::tree::play_action(s, &moves).map_err(|e| err(format!("illegal action {}: {}", lan, e)))?;
                let action = Action::from_vector(&moves, s);
                // A history keeps each action once (the strongest tag wins).
                let list = &mut book.positions.get_mut(h).unwrap().exact.iter_mut().find(|(x, _)| x == hist).unwrap().1;
                match list.iter_mut().find(|b| b.lan == lan) {
                    Some(b) => {
                        b.play |= play;
                        b.weight = b.weight.max(weight);
                    }
                    None => list.push(BookMove { action, lan, pgn: pgn.trim().to_string(), play, weight }),
                }
            } else {
                return Err(err(format!("unknown line {:?}", line)));
            }
        }
        for e in book.positions.values_mut() {
            e.merged = Self::merge(&e.exact, e.exact_only);
        }
        Ok(book)
    }

    /// What a history the book does not know gets (see `Entry::merged`).
    fn merge(exact: &[(u64, Vec<BookMove>)], exact_only: bool) -> Vec<BookMove> {
        if exact.len() == 1 && !exact_only {
            return exact[0].1.clone();
        }
        let mut out: Vec<BookMove> = Vec::new();
        for (_, moves) in exact {
            for m in moves {
                if out.iter().any(|o| o.lan == m.lan) {
                    continue;
                }
                let all: Vec<&BookMove> = exact.iter().filter_map(|(_, v)| v.iter().find(|x| x.lan == m.lan)).collect();
                let play = !exact_only && all.len() == exact.len() && all.iter().all(|x| x.play);
                let weight = if play { all.iter().map(|x| x.weight).min().unwrap_or(0) } else { 0 };
                out.push(BookMove { play, weight, ..m.clone() });
            }
        }
        out
    }

    /// The book the engine uses (`data/book_theory.txt`); empty if it does not parse (a test
    /// makes sure it does).
    pub fn theory() -> &'static Book {
        static BOOK: OnceLock<Book> = OnceLock::new();
        BOOK.get_or_init(|| Book::parse(include_str!("../../data/book_theory.txt")).unwrap_or_default())
    }

    /// Number of positions and of candidate actions.
    pub fn size(&self) -> (usize, usize) {
        (self.positions.len(), self.positions.values().map(|e| e.merged.len()).sum())
    }

    /// The opening's name at `s` ("Family: Variation: Line"), if the position carries one. A
    /// game's opening is the last name found along it.
    pub fn opening_name(&self, s: &State) -> Option<&str> {
        self.names.get(&s.frontier_hash()).map(|n| n.as_str())
    }

    /// Number of named positions.
    pub fn name_count(&self) -> usize {
        self.names.len()
    }

    /// All book actions (play and know) of `s`, if it is a book position.
    pub fn probe(&self, s: &State) -> Option<&[BookMove]> {
        let e = self.positions.get(&s.frontier_hash())?;
        let hist = s.hash();
        let v = e.exact.iter().find(|(x, _)| *x == hist).map_or(&e.merged, |(_, v)| v);
        Some(v.as_slice()).filter(|v| !v.is_empty())
    }

    /// Non-book actions of `s` that transpose into a book position. Played at `TRANSPOSE_WEIGHT`
    /// if that position has played actions and is not `{exact}`, otherwise known only.
    pub fn transpositions(&self, s: &State) -> Vec<BookMove> {
        let all = self.all_actions.get_or_init(|| {
            let mut seen = std::collections::HashSet::new();
            let mut v = Vec::new();
            for m in self.positions.values().flat_map(|e| e.exact.iter().flat_map(|(_, v)| v.iter())) {
                if seen.insert(m.lan.clone()) {
                    v.push((m.lan.clone(), m.pgn.clone()));
                }
            }
            v
        });
        let own = self.probe(s);
        // Only the actions of the turn being played can apply (their LAN starts with it).
        let (t, c) = s.get_present();
        let prefix = format!("(0T{})", t);
        let _ = c;
        let mut out = Vec::new();
        for (lan, pgn) in all.iter() {
            if !lan.starts_with(&prefix) || own.is_some_and(|o| o.iter().any(|m| &m.lan == lan)) {
                continue;
            }
            let Ok(moves) = crate::web::tree::parse_lan_moves(lan) else { continue };
            let Ok(child) = crate::web::tree::play_action(s, &moves) else { continue };
            let h = child.frontier_hash();
            let reached = self.probe(&child);
            if reached.is_some() || self.names.contains_key(&h) {
                let play = reached.is_some_and(|v| v.iter().any(|m| m.play)) && !self.positions.get(&h).is_some_and(|e| e.exact_only);
                out.push(BookMove {
                    action: Action::from_vector(&moves, s),
                    lan: lan.clone(),
                    pgn: pgn.clone(),
                    play,
                    weight: if play { TRANSPOSE_WEIGHT } else { 0 },
                });
            }
        }
        out
    }

    /// A `play` action of `s`, chosen with probability proportional to its weight using
    /// `seed`; `None` when `s` has none.
    pub fn choose(&self, s: &State, seed: u64) -> Option<BookMove> {
        let mut moves: Vec<BookMove> = self.probe(s).map(|v| v.to_vec()).unwrap_or_default();
        moves.extend(self.transpositions(s));
        let total: u64 = moves.iter().filter(|m| m.play).map(|m| m.weight as u64).sum();
        if total == 0 {
            return None;
        }
        let mut r = mix(seed ^ s.hash()) % total;
        for m in moves.into_iter().filter(|m| m.play) {
            if r < m.weight as u64 {
                return Some(m);
            }
            r -= m.weight as u64;
        }
        None
    }

    /// Total `play` weight of `s` (0 if none), for reporting.
    pub fn play_weight(&self, s: &State) -> u32 {
        let own: u32 = self.probe(s).map_or(0, |v| v.iter().filter(|m| m.play).map(|m| m.weight).sum());
        own + self.transpositions(s).iter().filter(|m| m.play).map(|m| m.weight).sum::<u32>()
    }
}

/// A random seed (from the standard library's per-process random keys).
pub fn random_seed() -> u64 {
    use std::hash::{BuildHasher, Hasher};
    static COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let mut h = std::collections::hash_map::RandomState::new().build_hasher();
    h.write_u64(COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed));
    h.finish()
}

fn mix(mut x: u64) -> u64 {
    x ^= x >> 33;
    x = x.wrapping_mul(0xff51afd7ed558ccd);
    x ^= x >> 33;
    x = x.wrapping_mul(0xc4ceb9fe1a85ec53);
    x ^ (x >> 33)
}

// ------------------------------------------------------------------ generation

/// One tagged (or untagged) action of a source line.
struct SrcMove {
    play: Option<bool>,
    weight: u32,
}

/// A source action's `{name ...}` tag.
type SrcName = Option<String>;

/// Build the book file from the annotated 5dpgn source (`data/book_theory_src.txt`).
/// Untagged actions inherit the tag given to the same action elsewhere.
pub fn generate(src: &str) -> Result<String, String> {
    generate_tuned(src, "")
}

/// (frontier key, action LAN) -> (played, weight).
pub type Tuning = HashMap<(u64, String), (bool, u32)>;

/// Parse the book's tuning layer (`data/book_tuning.txt`): tag and weight overrides keyed by
/// (`State::frontier_hash`, action LAN). Lines: `<key> <play|know> <weight> <LAN> ; <comment>`.
pub fn parse_tuning(text: &str) -> Result<Tuning, String> {
    let mut out = HashMap::new();
    for (n, line) in text.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let err = |e: &str| format!("tuning line {}: {}", n + 1, e);
        let (head, _) = line.split_once(';').unwrap_or((line, ""));
        let mut it = head.split_whitespace();
        let key = u64::from_str_radix(it.next().ok_or_else(|| err("no key"))?, 16).map_err(|_| err("bad key"))?;
        let play = match it.next() {
            Some("play") => true,
            Some("know") => false,
            _ => return Err(err("bad tag")),
        };
        let weight: u32 = it.next().and_then(|w| w.parse().ok()).ok_or_else(|| err("bad weight"))?;
        let lan = it.collect::<Vec<_>>().join(" ");
        if lan.is_empty() {
            return Err(err("no action"));
        }
        if out.insert((key, lan), (play, weight)).is_some() {
            return Err(err("duplicate entry"));
        }
    }
    Ok(out)
}

/// `generate` with a tuning layer applied (see `parse_tuning`).
pub fn generate_tuned(src: &str, tuning: &str) -> Result<String, String> {
    let tuning = parse_tuning(tuning)?;
    let mut used: std::collections::HashSet<(u64, String)> = std::collections::HashSet::new();
    use crate::core::variants::state_from_setup;
    use crate::web::pgn::{action_to_pgn_short, parse_5dpgn};
    use crate::web::record::setup_to_uci;
    use crate::web::tree::action_lan;

    struct Pos {
        /// A source line marked this position `{exact}` (see `Entry`).
        exact: bool,
        g: String,
        /// `State::frontier_hash` of the position (the tuning's key).
        frontier: u64,
        note: Vec<String>,
        moves: Vec<(String, String, SrcMove, usize)>,
        name: Option<String>,
    }
    let mut order: Vec<u64> = Vec::new();
    let mut pos: HashMap<u64, Pos> = HashMap::new();
    let mut note: Vec<String> = Vec::new();
    for (n, line) in src.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            note.clear();
            continue;
        }
        if let Some(c) = line.strip_prefix('#') {
            note.push(c.trim().to_string());
            continue;
        }
        let err = |e: String| format!("source line {}: {}", n + 1, e);
        let game = parse_5dpgn(line, None).map_err(err)?;
        let mut s = state_from_setup(&game.setup).map_err(err)?;
        let mut g = format!("G {} {} moves", game.setup.promotions.0, setup_to_uci(&game.setup));
        let mut node = &game.root;
        // From an action tagged {exact} on, the positions of this line are only valid for their history.
        let mut exact_on = false;
        let mut pending_note = std::mem::take(&mut note);
        while let Some(child) = node.children.first() {
            let act = child.action.as_ref().ok_or_else(|| err("action missing".into()))?;
            let mut tag = SrcMove { play: None, weight: 0 };
            let mut name: SrcName = None;
            let mut mark_exact = false;
            for c in &child.comments {
                let mut w = c.split_whitespace();
                match w.next() {
                    Some("name") => {
                        let n = c.trim().strip_prefix("name").unwrap_or("").trim().to_string();
                        if n.is_empty() {
                            return Err(err(format!("empty {{name}} after {}", child.text)));
                        }
                        name = Some(n);
                    }
                    Some("play") => {
                        tag.play = Some(true);
                        tag.weight = w.next().and_then(|x| x.parse().ok()).ok_or_else(|| err(format!("bad weight in {{{}}} after {}", c, child.text)))?;
                    }
                    Some("know") => tag.play = Some(false),
                    Some("exact") => mark_exact = true,
                    _ => return Err(err(format!("unknown tag {{{}}} after {}", c, child.text))),
                }
            }
            let lan = action_lan(&s, act);
            let next = crate::web::tree::play_action(&s, act.moves()).map_err(|e| err(format!("{}: {}", child.text, e)))?;
            let h = s.hash();
            let p = pos.entry(h).or_insert_with(|| {
                order.push(h);
                Pos { exact: false, g: g.clone(), frontier: s.frontier_hash(), note: std::mem::take(&mut pending_note), moves: Vec::new(), name: None }
            });
            p.exact |= exact_on;
            match p.moves.iter_mut().find(|m| m.0 == lan) {
                Some(m) => {
                    if let Some(play) = tag.play {
                        if let Some(old) = m.2.play
                            && (old != play || old && m.2.weight != tag.weight) {
                                return Err(err(format!("conflicting tags for {}", child.text)));
                            }
                        m.2 = tag;
                    }
                }
                None => p.moves.push((lan.clone(), action_to_pgn_short(&s, act), tag, n + 1)),
            }
            for m in act.moves() {
                g += &format!(" {}", m);
            }
            g += " submit";
            exact_on |= mark_exact;
            if let Some(n) = name {
                // The name belongs to the position after the action.
                let after = next.hash();
                let p = pos.entry(after).or_insert_with(|| {
                    order.push(after);
                    Pos { exact: false, g: g.clone(), frontier: next.frontier_hash(), note: Vec::new(), moves: Vec::new(), name: None }
                });
                match &p.name {
                    Some(old) if *old != n => return Err(err(format!("two names for one position: {:?} and {:?}", old, n))),
                    _ => p.name = Some(n),
                }
            }
            s = next;
            node = child;
        }
    }
    let mut out = String::from(
        "# Kairos opening book, generated by `ktools bookgen data/book_theory_src.txt` from the annotated\n\
         # 5dpgn lines there (sources and tags explained in that file); do not edit by hand.\n\
         # P <G line>: a book position; m <play|know> <weight> <action LAN> ; <5dpgn>: its actions.\n",
    );
    for h in order {
        let p = &pos[&h];
        if !p.note.is_empty() {
            out.push('\n');
            for l in &p.note {
                out += &format!("# {}\n", l);
            }
        }
        out += &format!("P {}\n", p.g);
        if p.exact {
            out += "E\n";
        }
        if let Some(n) = &p.name {
            out += &format!("N {}\n", n);
        }
        for (lan, pgn, tag, line) in &p.moves {
            let (play, weight) = match tuning.get(&(p.frontier, lan.clone())) {
                Some(&(play, weight)) => {
                    used.insert((p.frontier, lan.clone()));
                    (play, weight)
                }
                None => {
                    let Some(play) = tag.play else {
                        return Err(format!("source line {}: action {} is tagged nowhere", line, pgn));
                    };
                    (play, tag.weight)
                }
            };
            out += &format!("m {} {} {} ; {}\n", if play { "play" } else { "know" }, if play { weight } else { 0 }, lan, pgn);
        }
    }
    if let Some(((k, lan), _)) = tuning.iter().find(|(k, _)| !used.contains(*k)) {
        return Err(format!("tuning entry {:016x} {} matches no action of the book", k, lan));
    }
    Ok(out)
}
